-- Clip registry. Every animation access goes through here, so clips can be replaced (new dict,
-- other clip, other flags/blend times) without touching gameplay code:
--   * shared/clips_data.lua is generated by jj_zombie_dev/tools/build-anims.mjs
--   * Config.ClipOverrides (config/config.lua) can redirect any entry to another dict/clip.
Clips = {}

local function data()
    return ClipData and ClipData.scenes or {}
end

-- Raw registry entry: { name, variant, dict, duration, loop, actors = { role = clipName }, events, meta, playback,
--   origins = { role = { x, y, z, yaw } } }. origins (paired scenes only): start transform of each actor
--   in the scene frame; the actor's clip starts at identity there (see client/finisher.lua).
function Clips.entry(name, variant)
    local key = (variant and variant ~= '') and (name .. ':' .. variant) or name
    local e = data()[key]
    local ov = Config.ClipOverrides and Config.ClipOverrides[key]
    if ov then
        e = e and JJZ.U.copy(e) or { name = name, variant = variant or '', actors = {}, events = {}, meta = {}, playback = {} }
        for k, v in pairs(ov) do e[k] = v end
    end
    return e
end

-- Single-actor clip: returns dict, clip, entry (nil if unknown).
function Clips.single(name, variant)
    local e = Clips.entry(name, variant)
    if not e then return nil end
    local clip = e.clip
    if not clip then
        for _, c in pairs(e.actors or {}) do clip = c; break end
    end
    return e.dict, clip, e
end

-- Pair/scene clip for a role ('victim', 'zombie').
function Clips.role(entry, role)
    return entry and entry.actors and entry.actors[role] or nil
end

-- Events of an entry, sorted by time: { {name=, t=, phase=, actor=}, ... }
function Clips.events(entry)
    local list = {}
    for _, ev in ipairs(entry and entry.events or {}) do list[#list + 1] = ev end
    table.sort(list, function(a, b) return a.t < b.t end)
    return list
end

-- Time (seconds) of the first event with this name, or nil.
function Clips.eventTime(entry, eventName)
    for _, ev in ipairs(entry and entry.events or {}) do
        if ev.name == eventName then return ev.t end
    end
    return nil
end

-- All variants of a scene name: { [variant] = entry }
function Clips.variants(name)
    local out = {}
    for key, e in pairs(data()) do
        if e.name == name then out[e.variant or ''] = e end
    end
    return out
end

-- Dictionaries referenced by the registry (for preloading/cleanup).
function Clips.dicts()
    local set, list = {}, {}
    for _, e in pairs(data()) do
        if e.dict and not set[e.dict] then set[e.dict] = true; list[#list + 1] = e.dict end
    end
    if Config.ClipOverrides then
        for _, ov in pairs(Config.ClipOverrides) do
            if ov.dict and not set[ov.dict] then set[ov.dict] = true; list[#list + 1] = ov.dict end
        end
    end
    table.sort(list)
    return list
end

-- Playback hints with defaults.
function Clips.playback(entry)
    local p = entry and entry.playback or {}
    return {
        blendIn = p.blendIn or 4.0,
        blendOut = p.blendOut or -4.0,
        flags = p.flags or 0,
        rate = p.rate or 1.0,
    }
end
